options(stringsAsFactors=FALSE)
root <- '.'; out <- 'revision_stage5'
readc <- function(p) read.csv(file.path(root,p),check.names=FALSE,fileEncoding='UTF-8-BOM')
mi <- readc('revision_stage1/stage1b_full_refit/STAGE1B_FULL_MODEL_RESULTS_miRNA.csv')
ge <- readc('revision_stage1/stage1b_full_refit/STAGE1B_FULL_MODEL_RESULTS_GENCODE.csv')
core <- readc('revision_stage1/stage1b_full_refit/STAGE1B_STRICT_CORE_ROBUST.csv')
corr <- readc('revision_stage4/STAGE4_CORRELATION_SUMMARY.csv')
master <- readc(file.path(out,'STAGE5_RESULTS_MASTER.csv'))
checks <- list(); add <- function(id,desc,ok,evidence,severity='CRITICAL') checks[[length(checks)+1]] <<- data.frame(id,description=desc,status=if(ok)'PASS' else 'FAIL',severity,evidence)
add('C01','M1 miRNA count = 192',sum(mi$M1_significant,na.rm=T)==192,'STAGE1B full miRNA results')
add('C02','M1 GENCODE count = 200',sum(ge$M1_significant,na.rm=T)==200,'STAGE1B full GENCODE results')
add('C03','M3 counts = 146/145',sum(mi$M3_significant,na.rm=T)==146 && sum(ge$M3_significant,na.rm=T)==145,'Stage1B M3 flags')
add('C04','M4 counts = 70/143',sum(mi$M4_significant,na.rm=T)==70 && sum(ge$M4_significant,na.rm=T)==143,'Stage1B M4 flags')
add('C05','Strict core = 16/33',sum(core$layer=='miRNA')==16 && sum(core$layer=='GENCODE')==33,'STAGE1B_STRICT_CORE_ROBUST.csv')
add('C06','Strict core contains no RS boundary',!any(core$any_RS_boundary),'strict-core flags')
add('C07','QC paired N = 141',nrow(readc('revision_stage0c/data/QC_PASS_ONLY_141_pairs.csv'))==141,'QC PASS-only pair list')
add('C08','FULL paired N = 153',nrow(readc('revision_stage0c/data/FULL_153_pairs.csv'))==153,'FULL pair list')
add('C09','RAW paired Pearson exact',abs(corr$estimate[corr$branch=='PRIMARY_FULL_RAW' & corr$metric=='pair_Pearson'][1]-0.3691689)<1e-6,'Stage4 correlation summary')
add('C10','CLR paired Pearson exact',abs(corr$estimate[corr$branch=='PRIMARY_FULL_CLR' & corr$metric=='pair_Pearson'][1]-0.8607)<1e-3,'Stage4 correlation summary')
add('C11','Original miRNA direction 189/3',sum(mi$M1_significant & mi$M1_slope<0,na.rm=T)==189 && sum(mi$M1_significant & mi$M1_slope>0,na.rm=T)==3,'Stage1B miRNA M1 slopes')
add('C12','Representative miRNA selection is frozen strict-core',all(c('hsa-miR-375','hsa-miR-323a-3p','hsa-miR-148a-5p') %in% core$feature),'Figure 3 source rule')
add('C13','Figure 4 main representatives are strict-core',all(c('MT-TL2:Mt_tRNA','RN7SL1:antisense','IL8:protein_coding','HBA1:protein_coding') %in% core$feature),'Figure 4 source rule')
main <- file.path(out,'02_main_figures',paste0('Figure_',1:5,'_revised'))
add('C14','All main figures have SVG/PDF/PNG/TIFF',all(unlist(lapply(main,function(x)file.exists(paste0(x,c('.svg','.pdf','.png','.tiff')))))),'02_main_figures')
supp_names <- c('Supplementary_Figure_S1_QC_sensitivity','Supplementary_Figure_S2_CLR_sensitivity','Supplementary_Figure_S3_random_slope_CR2','Supplementary_Figure_S4_composition_analysis_recomposed','Supplementary_Figure_S5_original_miRNA_representatives','Supplementary_Figure_S6_endpoint_sensitivity_recomposed','Supplementary_Figure_S7_cross_layer_technical_consistency')
supp <- file.path(out,'03_supplementary_figures',supp_names)
add('C15','Seven active supplementary figures have SVG/PDF/PNG/TIFF',all(unlist(lapply(supp,function(x)file.exists(paste0(x,c('.svg','.pdf','.png','.tiff')))))),'03_supplementary_figures active figure set')
add('C16','Graphical abstract has SVG/PDF/PNG/TIFF',all(file.exists(file.path(out,'05_graphical_abstract',paste0('Graphical_Abstract_revised',c('.svg','.pdf','.png','.tiff'))))),'05_graphical_abstract')
add('C17','Master results has provenance columns',all(c('source_file','model','n_subjects','n_observations','reproducible_script','figure_or_table')%in%names(master)),'STAGE5_RESULTS_MASTER.csv')
add('C18','Mean/categorical evidence boundaries explicitly recorded',all(c('mean_gradient_sensitivity','categorical_temporal_sensitivity')%in%master$section),'STAGE5_RESULTS_MASTER.csv')
add('C19','Supplementary Data 3 copied unchanged',unname(tools::md5sum('revision_stage0d/source_extract/TRACKB_REVISION_TRANSFER_PACKAGE/03_SUPPLEMENTARY_MATERIALS/Supplementary_Data/Supplementary_Data_3_provenance_crosswalk.csv'))==unname(tools::md5sum(file.path(out,'04_tables/Supplementary_Data_3_provenance_crosswalk_UNCHANGED.csv'))),'MD5 equality')
figfiles <- list.files(file.path(out,'02_main_figures'),pattern='\\.(tiff|pdf)$',full.names=T)
add('C20','Every main figure file <10 MB',all(file.info(figfiles)$size<10*1024^2),'BMC figure upload limit')
res <- do.call(rbind,checks)
write.csv(res,file.path(out,'STAGE5_RESULTS_CONSISTENCY_CHECK.csv'),row.names=FALSE)
write.csv(res,file.path(out,'07_validation','STAGE5_RESULTS_CONSISTENCY_CHECK.csv'),row.names=FALSE)
if(any(res$status!='PASS')) stop('Stage 5 validation failed: ',paste(res$id[res$status!='PASS'],collapse=', '))
cat('All',nrow(res),'Stage 5 checks passed.\n')

